INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(240387, 15046, 6855, '<td valign="top">One of my top picks for the week - I''m sure you''ll be in the top 5!</td>', 'One of my top picks for the week - I''m sure you''ll be in the top 5!', '2003-03-18 14:25:35.000000', NULL, 1),
(240575, 15004, 6328, '<td valign="top">Yep, not much snow up there any more.  Green sure looks nice doesn''t it?<br/>I really like that blue sky against those mountains.<br/>Visual impact upon first looking at it is fantastic.  Great composition.</td>', 'Yep, not much snow up there any more.  Green sure looks nice doesn''t it?I really like that blue sky against those mountains.Visual impact upon first looking at it is fantastic.  Great composition.', '2003-03-18 16:20:48.000000', NULL, 1),
(240577, 14992, 6328, '<td valign="top">Composition is nice and simple<br/>Idea is nice and original, well executed<br/>Fits the Challenge<br/>Lighting looks great<br/>Focus seems just fine all round<br/>Colours are fine<br/>I really like your framing with the thin green line then the large black frame.<br/>lovely photography.</td>', 'Composition is nice and simpleIdea is nice and original, well executedFits the ChallengeLighting looks greatFocus seems just fine all roundColours are fineI really like your framing with the thin green line then the large black frame.lovely photography.', '2003-03-18 16:23:29.000000', NULL, 1),
(240635, 15036, 554, '<td valign="top">WOW, another First Place entry!!!!</td>', 'WOW, another First Place entry!!!!', '2003-03-18 18:23:46.000000', NULL, 1),
(240637, 15034, 554, '<td valign="top">Beautiful Portrat.....well posed...10</td>', 'Beautiful Portrat.....well posed...10', '2003-03-18 18:25:41.000000', NULL, 1),
(240645, 15145, 6328, '<td valign="top">Composition is nice and simple<br/>Idea is different/good originality<br/>Fits the Challenge okay<br/>Lighting is fine, bit of a shadow under the leaves<br/>Focus looks okay<br/>Colours are okay<br/></td>', 'Composition is nice and simpleIdea is different/good originalityFits the Challenge okayLighting is fine, bit of a shadow under the leavesFocus looks okayColours are okay', '2003-03-18 18:45:41.000000', NULL, 1),
(240646, 15116, 6328, '<td valign="top">Fits the Challenge okay<br/>Lighting is fine, lot of shadow on the wall though<br/>Focus is fine<br/>Colour is okay<br/></td>', 'Fits the Challenge okayLighting is fine, lot of shadow on the wall thoughFocus is fineColour is okay', '2003-03-18 18:46:42.000000', NULL, 1),
(240647, 15108, 6328, '<td valign="top">Composition is nice and simple<br/>Idea is different/good originality<br/>Fits the Challenge okay<br/>Lighting is fine<br/>Focus is fine<br/>Colour is okay, I like the blue eyes<br/>good green on the border<br/></td>', 'Composition is nice and simpleIdea is different/good originalityFits the Challenge okayLighting is fineFocus is fineColour is okay, I like the blue eyesgood green on the border', '2003-03-18 18:47:46.000000', NULL, 1),
(240648, 15150, 6328, '<td valign="top">Meets Challenge<br/>Visual impact is good,<br/>Originality is nice, good idea<br/>Colour looks nice<br/></td>', 'Meets ChallengeVisual impact is good,Originality is nice, good ideaColour looks nice', '2003-03-18 18:49:00.000000', NULL, 1),
(240650, 15023, 6328, '<td valign="top">Visual impact is great<br/>Focus is good, nice and sharp<br/>Good idea for photo<br/>Colours are different<br/></td>', 'Visual impact is greatFocus is good, nice and sharpGood idea for photoColours are different', '2003-03-18 18:50:45.000000', NULL, 1),
(240651, 15027, 6328, '<td valign="top">Seems like too much lighting, too bright to get a good look at the green.<br/>focus seems out because of the lighting, second set of leaves seems blurry<br/>you''ve cut the top of the petals off when you cropped.</td>', 'Seems like too much lighting, too bright to get a good look at the green.focus seems out because of the lighting, second set of leaves seems blurryyou''ve cut the top of the petals off when you cropped.', '2003-03-18 18:53:46.000000', NULL, 1),
(240652, 14983, 6328, '<td valign="top">Visual impact is great<br/>Focus is good, nice and sharp<br/>Good idea for photo<br/>Colours of green are good<br/>You certainly got close to the ground for this shot.<br/>You meet the Challenge, that''s for sure.<br/></td>', 'Visual impact is greatFocus is good, nice and sharpGood idea for photoColours of green are goodYou certainly got close to the ground for this shot.You meet the Challenge, that''s for sure.', '2003-03-18 18:55:04.000000', NULL, 1),
(240653, 15043, 6328, '<td valign="top">Now this guy is cute!  Is he Irish?<br/>Great idea for a photo, something new you''ve come up with. . .<br/>Lovely mix of colour, nice blue eyes, nice background too.<br/>Focus is great, nice and sharp,<br/>Lighting is good, not overdone<br/>I like your green framing also.<br/>What''s that bit of discoloration down at the bottom left corner?</td>', 'Now this guy is cute!  Is he Irish?Great idea for a photo, something new you''ve come up with. . .Lovely mix of colour, nice blue eyes, nice background too.Focus is great, nice and sharp,Lighting is good, not overdoneI like your green framing also.What''s that bit of discoloration down at the bottom left corner?', '2003-03-18 18:59:22.000000', NULL, 1),
(240654, 15000, 6328, '<td valign="top">Composition is nice and simple<br/>Idea is nice and original, well executed<br/>Fits the Challenge<br/>Lighting looks great, not many shadows here!<br/>Focus looks okay<br/>Colours are fine<br/>Nice shot.</td>', 'Composition is nice and simpleIdea is nice and original, well executedFits the ChallengeLighting looks great, not many shadows here!Focus looks okayColours are fineNice shot.', '2003-03-18 19:00:44.000000', NULL, 1),
(240668, 15032, 3575, '<td valign="top">Challenge met. Nice detail and I like the grainy texture. The composition is a little off for me though, I would like that elaf on the top not to be cropped since so little of it is and then I don''t know what the the handle-like object is in the lower right. Overall, very artistic.</td>', 'Challenge met. Nice detail and I like the grainy texture. The composition is a little off for me though, I would like that elaf on the top not to be cropped since so little of it is and then I don''t know what the the handle-like object is in the lower right. Overall, very artistic.', '2003-03-18 19:22:51.000000', NULL, 1),
(240670, 15012, 4536, '<td valign="top">My favorite of the challenge, awesome lighting and composition.</td>', 'My favorite of the challenge, awesome lighting and composition.', '2003-03-18 19:23:44.000000', NULL, 1),
(240677, 14995, 3575, '<td valign="top">Really well done photo. Perfect DOF and exposure and composition.</td>', 'Really well done photo. Perfect DOF and exposure and composition.', '2003-03-18 19:26:13.000000', NULL, 1),
(240683, 15039, 3575, '<td valign="top">One day I''m going to try this shot. Nicely done!</td>', 'One day I''m going to try this shot. Nicely done!', '2003-03-18 19:29:16.000000', NULL, 1),
(240686, 15145, 3575, '<td valign="top">Very nice, clean (pun intended) product shot.  I don''t care for the surface it was photographed on, I would have liked a clean/smooth surface, but the composition is nice. Perhaps a little back lighting to get rid of the shadow on the top.</td>', 'Very nice, clean (pun intended) product shot.  I don''t care for the surface it was photographed on, I would have liked a clean/smooth surface, but the composition is nice. Perhaps a little back lighting to get rid of the shadow on the top.', '2003-03-18 19:31:17.000000', NULL, 1),
(240690, 15128, 3575, '<td valign="top">I tried to photograph moss on bark yesterday with no luck whatsoever, I think I would have liked more DOF in the front so that I could actually see the detail of the large, orange thing. But I like the DOF as far as the nice detail on top and the nice soft background. You added a lot of interest to the composition by cropping at this angle, nice detail.</td>', 'I tried to photograph moss on bark yesterday with no luck whatsoever, I think I would have liked more DOF in the front so that I could actually see the detail of the large, orange thing. But I like the DOF as far as the nice detail on top and the nice soft background. You added a lot of interest to the composition by cropping at this angle, nice detail.', '2003-03-18 19:34:06.000000', NULL, 1),
(240692, 14971, 3575, '<td valign="top">Isn''t that beautiful! It looks like velvet drapery. I like the little bit of grain, it adds an interesting appeal. I also like that your leaf covers almost all of the frame with one, tiny little exception. I also like the contrast of very light and very dark. This is a really nice image.</td>', 'Isn''t that beautiful! It looks like velvet drapery. I like the little bit of grain, it adds an interesting appeal. I also like that your leaf covers almost all of the frame with one, tiny little exception. I also like the contrast of very light and very dark. This is a really nice image.', '2003-03-18 19:36:27.000000', NULL, 1),
(240696, 15149, 3575, '<td valign="top">Exceptional! Almost perfect but you can''t spot edit the spot so I won''t take away any points. I think this is one of my few 10''s this time.  The more I look at it the more I like it. The choices you made all around work so well. Well, I can''t spend all day on this so, good luck!</td>', 'Exceptional! Almost perfect but you can''t spot edit the spot so I won''t take away any points. I think this is one of my few 10''s this time.  The more I look at it the more I like it. The choices you made all around work so well. Well, I can''t spend all day on this so, good luck!', '2003-03-18 19:39:15.000000', NULL, 1),
(240704, 15126, 3575, '<td valign="top">Hey, It''s Green! I think there needs to be more of a focal point, it''s hard to tell what I''m supposed to look at. But, maybe I''m just supposed to enjoy all the different shades of green, which I do.</td>', 'Hey, It''s Green! I think there needs to be more of a focal point, it''s hard to tell what I''m supposed to look at. But, maybe I''m just supposed to enjoy all the different shades of green, which I do.', '2003-03-18 19:43:00.000000', NULL, 1),
(240707, 15024, 3575, '<td valign="top">Lovely fine art photography. Honestly though, I think I would like a different cropping but your lighting and exposure are perfect. I love the texture of the basket. I can''t wait to find out what camera settings you used. Nice job.</td>', 'Lovely fine art photography. Honestly though, I think I would like a different cropping but your lighting and exposure are perfect. I love the texture of the basket. I can''t wait to find out what camera settings you used. Nice job.', '2003-03-18 19:44:32.000000', NULL, 1),
(240719, 15029, 3575, '<td valign="top">Very creative! Beautiful sky and lovely shade of green. I keep changing my mind about the tilt on the stop sign, I would like to see it straight but then again, it adds some perspective like this. One more think, The rich colors are wonderful!</td>', 'Very creative! Beautiful sky and lovely shade of green. I keep changing my mind about the tilt on the stop sign, I would like to see it straight but then again, it adds some perspective like this. One more think, The rich colors are wonderful!', '2003-03-18 19:47:01.000000', NULL, 1),
(240722, 15144, 3575, '<td valign="top">Just goes to show us, our money really isn''t very green. It could be a little sharper but the exposure is good.</td>', 'Just goes to show us, our money really isn''t very green. It could be a little sharper but the exposure is good.', '2003-03-18 19:48:17.000000', NULL, 1),
(240726, 15130, 3575, '<td valign="top">That looks soooo good! Is it me or is the glass turned just a little off center to the right? I love the bubbles, it looks so cool and refreshing.</td>', 'That looks soooo good! Is it me or is the glass turned just a little off center to the right? I love the bubbles, it looks so cool and refreshing.', '2003-03-18 19:49:42.000000', NULL, 1),
(240730, 14982, 3575, '<td valign="top">Made my mouth water! I like the composition. Maybe just a little over exposed.</td>', 'Made my mouth water! I like the composition. Maybe just a little over exposed.', '2003-03-18 19:51:14.000000', NULL, 1),
(240735, 15043, 554, '<td valign="top">EXCELLENT!!!!  First Place ...the lighting, focus, colors and BLACK bacground are PERFECT</td>', 'EXCELLENT!!!!  First Place ...the lighting, focus, colors and BLACK bacground are PERFECT', '2003-03-18 19:53:46.000000', NULL, 1),
(240741, 14963, 3575, '<td valign="top">Clever idea! I think the surface you chose to shoot this on brings the overall appeal down a lot. A clean, smooth surface like a counter top might have worked well. And, I think that the stem end on one of the avacados should be turned under. There are also some harsh shadows that could be prevented by having another light in the front of the subject. I think the exposure and detail are very good. Technically, except for shadows, it''s very good.</td>', 'Clever idea! I think the surface you chose to shoot this on brings the overall appeal down a lot. A clean, smooth surface like a counter top might have worked well. And, I think that the stem end on one of the avacados should be turned under. There are also some harsh shadows that could be prevented by having another light in the front of the subject. I think the exposure and detail are very good. Technically, except for shadows, it''s very good.', '2003-03-18 19:57:29.000000', NULL, 1),
(240744, 15114, 3575, '<td valign="top">I like, I like! Clean, perfectly composed and shot. Very good.</td>', 'I like, I like! Clean, perfectly composed and shot. Very good.', '2003-03-18 19:58:26.000000', NULL, 1),
(240755, 14984, 3575, '<td valign="top">Slime never looked so beautiful! Very creative! You must have had a ball doing this one, especially when you saw how well it turned out.</td>', 'Slime never looked so beautiful! Very creative! You must have had a ball doing this one, especially when you saw how well it turned out.', '2003-03-18 20:04:43.000000', NULL, 1),
(240759, 14983, 3575, '<td valign="top">Wonderful macro work! I love the 3d effect of the DOF. Nice job</td>', 'Wonderful macro work! I love the 3d effect of the DOF. Nice job', '2003-03-18 20:11:21.000000', NULL, 1),
(240761, 15004, 3575, '<td valign="top">Amazing mountains. I really like it, just wish it was bigger so I could see more of the detail but we''re limited to that darn 640 pixels. But, what I can tell it has amazing detail and clarity. Only thing, I think there''s too much sky. It''s so bright and blue that my attention is continually drawn away from the gorgeous mounains.</td>', 'Amazing mountains. I really like it, just wish it was bigger so I could see more of the detail but we''re limited to that darn 640 pixels. But, what I can tell it has amazing detail and clarity. Only thing, I think there''s too much sky. It''s so bright and blue that my attention is continually drawn away from the gorgeous mounains.', '2003-03-18 20:14:28.000000', NULL, 1),
(240765, 15011, 3575, '<td valign="top">Can there be too much green? Yes, but not here. I love it! Nice composition. The softness works well.</td>', 'Can there be too much green? Yes, but not here. I love it! Nice composition. The softness works well.', '2003-03-18 20:17:12.000000', NULL, 1),
(240766, 14992, 3575, '<td valign="top">Absoultely wonderful and you gave me chills. What a wonderful sentiment in these times. 10! PS: it''s very well done too. :)</td>', 'Absoultely wonderful and you gave me chills. What a wonderful sentiment in these times. 10! PS: it''s very well done too. :)', '2003-03-18 20:18:25.000000', NULL, 1),
(240767, 14959, 3575, '<td valign="top">LOL, Excellent DOF use and perfectly composed. Don''t know about the little plastick lizard but it cracked me up.</td>', 'LOL, Excellent DOF use and perfectly composed. Don''t know about the little plastick lizard but it cracked me up.', '2003-03-18 20:19:50.000000', NULL, 1),
(240768, 15034, 3575, '<td valign="top">Adorable photo, lighting is perfect! Just one problem, here feet are missing. It is really a nice portrait though. I think it''s framable.</td>', 'Adorable photo, lighting is perfect! Just one problem, here feet are missing. It is really a nice portrait though. I think it''s framable.', '2003-03-18 20:23:50.000000', NULL, 1),
(240771, 15115, 3575, '<td valign="top">Beautiful green field. I think I was there this weekend. Actually, I was in the Skagit Valley in Washington State and it looks just like this. You probably have received comments about the slant on the horizon but at the angle you shot it, it works, just adds perspective. Although I am a real stickler for straight horizons, it doesn''t always have to be. Anyway, the sky is slightly over exposed. I know  two ways to remedy a problem like that, 1) take two photos, one with the sky correctly exposed and the other with the land correctly exposed and then use PS to merge the two together(not legal in the challenges). 2) use a graduated Neutral Density filter. Have the darker portion covering the sky and then expose the land.</td>', 'Beautiful green field. I think I was there this weekend. Actually, I was in the Skagit Valley in Washington State and it looks just like this. You probably have received comments about the slant on the horizon but at the angle you shot it, it works, just adds perspective. Although I am a real stickler for straight horizons, it doesn''t always have to be. Anyway, the sky is slightly over exposed. I know  two ways to remedy a problem like that, 1) take two photos, one with the sky correctly exposed and the other with the land correctly exposed and then use PS to merge the two together(not legal in the challenges). 2) use a graduated Neutral Density filter. Have the darker portion covering the sky and then expose the land.', '2003-03-18 20:33:49.000000', NULL, 1),
(240773, 15022, 3575, '<td valign="top">Not a 4 leafer but WONDERFUL! Simple, elegant and perfectuly exposed. Wow, what excellent DOF.</td>', 'Not a 4 leafer but WONDERFUL! Simple, elegant and perfectuly exposed. Wow, what excellent DOF.', '2003-03-18 20:34:53.000000', NULL, 1),
(240777, 15036, 3575, '<td valign="top">10! 10+ if you can recover that little bit of elbow but this is absolutely perfect! Beautiful pose, beautiful girl and amazing, amazing lighting and exposure! Thank you for submitting this gorgeous, beathtaking image of sweetness.</td>', '10! 10+ if you can recover that little bit of elbow but this is absolutely perfect! Beautiful pose, beautiful girl and amazing, amazing lighting and exposure! Thank you for submitting this gorgeous, beathtaking image of sweetness.', '2003-03-18 20:39:56.000000', NULL, 1),
(240827, 15036, 6328, '<td valign="top">Is she Irish, though?<br/>Very pretty little girl!  Lovely Portrait. . .<br/>Composition is nice and simple<br/>Idea is nice and original, well executed<br/>Fits the Challenge, that''s for sure!<br/>Lighting looks great<br/>Focus is excellent<br/>Colours are fine<br/>P:osturing of hands are just right, smile is great, eyes are smiling, what else could you ask for?  This all adds up to a very striking/emotional St. Patrick''s Day Portrait that you should be proud of, and I think it richly deserves a. . .10<br/></td>', 'Is she Irish, though?Very pretty little girl!  Lovely Portrait. . .Composition is nice and simpleIdea is nice and original, well executedFits the Challenge, that''s for sure!Lighting looks greatFocus is excellentColours are fineP:osturing of hands are just right, smile is great, eyes are smiling, what else could you ask for?  This all adds up to a very striking/emotional St. Patrick''s Day Portrait that you should be proud of, and I think it richly deserves a. . .10', '2003-03-18 21:26:52.000000', NULL, 1),
(240852, 15145, 2352, '<td valign="top">I like this fresh, clean, sharp focused and well lit shot. Simple idea well executed. This shows that less can be more! Very refreshing! Well done.  -Clicker-</td>', 'I like this fresh, clean, sharp focused and well lit shot. Simple idea well executed. This shows that less can be more! Very refreshing! Well done.  -Clicker-', '2003-03-18 21:38:28.000000', NULL, 1),
