(241765, 15001, 6328, '<td valign="top">idea for the photo is really different and well photographed for a night shot..<br/>Fits the Challenge;  focus is great, as sharp as can be for night time, colours are good.<br/> <br/></td>', 'idea for the photo is really different and well photographed for a night shot..Fits the Challenge;  focus is great, as sharp as can be for night time, colours are good. ', '2003-03-19 19:44:00.000000', NULL, 1),
(241766, 15138, 6328, '<td valign="top">Composition is quite good, certainly meets the Challenge<br/>Visual impact is great with nice colors of green and the red on that ladder thing.<br/>Focus is good, nice and sharp, great idea for a photo.  Kinda wished you had shown the whole tower on that upper window.<br/> <br/></td>', 'Composition is quite good, certainly meets the ChallengeVisual impact is great with nice colors of green and the red on that ladder thing.Focus is good, nice and sharp, great idea for a photo.  Kinda wished you had shown the whole tower on that upper window. ', '2003-03-19 19:47:07.000000', NULL, 1),
(241768, 15149, 6328, '<td valign="top">Composition is quite good, lovely colours in that umbrella and I really like the visual impact that it gives off when you first look at it.<br/>Focus is good, nice and sharp, colours are good, I like the black lines against all the green.<br/></td>', 'Composition is quite good, lovely colours in that umbrella and I really like the visual impact that it gives off when you first look at it.Focus is good, nice and sharp, colours are good, I like the black lines against all the green.', '2003-03-19 19:49:24.000000', NULL, 1),
(241769, 14971, 6328, '<td valign="top">Composition is good; Photograph meets the Challenge; Visual impact is good; Focus is good; Shows good idea and originality; Colour of photograph is good.<br/>Why didn''t you crop out the upper right hand corner where the light shines through?</td>', 'Composition is good; Photograph meets the Challenge; Visual impact is good; Focus is good; Shows good idea and originality; Colour of photograph is good.Why didn''t you crop out the upper right hand corner where the light shines through?', '2003-03-19 19:50:53.000000', NULL, 1),
(241771, 15024, 6328, '<td valign="top">Those apples make me hungry.  Like your choice of a background.  Your sidelighting is a good source of lighting for this photograph.  The apples are a really nice green. I don''t know why, but your apples seem somewhat blurry, did you do this on purpose? or is it because you enlarged it too much?  I like the brown color of the basket.</td>', 'Those apples make me hungry.  Like your choice of a background.  Your sidelighting is a good source of lighting for this photograph.  The apples are a really nice green. I don''t know why, but your apples seem somewhat blurry, did you do this on purpose? or is it because you enlarged it too much?  I like the brown color of the basket.', '2003-03-19 19:53:07.000000', NULL, 1),
(241772, 15033, 5266, '<td valign="top">Awesome!!!  I had this same idea, but obviously didn''t follow through.  The only thing I can pick at is that the flag is tattered at the edges.  Tsk Tsk!!  But I love the folds in the flag, the tint of green you''ve chosen, just love it!!</td>', 'Awesome!!!  I had this same idea, but obviously didn''t follow through.  The only thing I can pick at is that the flag is tattered at the edges.  Tsk Tsk!!  But I love the folds in the flag, the tint of green you''ve chosen, just love it!!', '2003-03-19 19:54:47.000000', NULL, 1),
(241773, 15014, 6328, '<td valign="top">Nice color o'' the green sponge.  I just don''t get the rest of it though.  Nice clear focus up to the bubbly, lighting is nice on the green end of the sponge.</td>', 'Nice color o'' the green sponge.  I just don''t get the rest of it though.  Nice clear focus up to the bubbly, lighting is nice on the green end of the sponge.', '2003-03-19 19:55:00.000000', NULL, 1),
(241774, 15030, 5266, '<td valign="top">This is wonderful - you caught my eye when I saw the thumbnail and the full size is even better.  Great detail on the shamrock leaf - nice background</td>', 'This is wonderful - you caught my eye when I saw the thumbnail and the full size is even better.  Great detail on the shamrock leaf - nice background', '2003-03-19 19:56:08.000000', NULL, 1),
(241775, 15038, 6328, '<td valign="top">Wow, are you close, or what?  Nice and green too, so I guess you meet the Challenge.  hey, wait a minute, I think I can see YOU in there!  Yes, there yu r. . .<br/>two legs, upr bdy, camera.  Nice shot, very original idea!</td>', 'Wow, are you close, or what?  Nice and green too, so I guess you meet the Challenge.  hey, wait a minute, I think I can see YOU in there!  Yes, there yu r. . .two legs, upr bdy, camera.  Nice shot, very original idea!', '2003-03-19 19:56:53.000000', NULL, 1),
(241776, 14992, 5266, '<td valign="top">Amen to that - great title, great idea!!  And we need a little peace this week.  The reflections off the leaves are a bit harsh, but the green is a great shade.</td>', 'Amen to that - great title, great idea!!  And we need a little peace this week.  The reflections off the leaves are a bit harsh, but the green is a great shade.', '2003-03-19 19:57:24.000000', NULL, 1),
(241777, 15029, 5266, '<td valign="top">Love the background.  Like the concept.  Good job</td>', 'Love the background.  Like the concept.  Good job', '2003-03-19 19:57:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(241779, 15126, 6328, '<td valign="top">nice and bright idea.  Color is great, Lighting is bright.  Focus is great in the middle of the fennel.  You certainly meet the Challenge, don''t you?</td>', 'nice and bright idea.  Color is great, Lighting is bright.  Focus is great in the middle of the fennel.  You certainly meet the Challenge, don''t you?', '2003-03-19 19:58:09.000000', NULL, 1),
(241780, 15127, 554, '<td valign="top">nice vivid colors....my objection is you not including all of the subject...I know, negetive space.  Just doesn''t work here.</td>', 'nice vivid colors....my objection is you not including all of the subject...I know, negetive space.  Just doesn''t work here.', '2003-03-19 19:58:16.000000', NULL, 1),
(241781, 14976, 6328, '<td valign="top">Just don''t what to say about this.  Nice green color, so you must meet the Challenge, right?</td>', 'Just don''t what to say about this.  Nice green color, so you must meet the Challenge, right?', '2003-03-19 19:58:44.000000', NULL, 1),
(241782, 14989, 5266, '<td valign="top">The green doesn''t really show here.  It''s almost a silvery color.  I don''t like the stray hairs behind the necklace.</td>', 'The green doesn''t really show here.  It''s almost a silvery color.  I don''t like the stray hairs behind the necklace.', '2003-03-19 19:58:46.000000', NULL, 1),
(241783, 15030, 6328, '<td valign="top">Lovely color against the blue sky and certainly looks nice against that white cloud.</td>', 'Lovely color against the blue sky and certainly looks nice against that white cloud.', '2003-03-19 19:59:21.000000', NULL, 1),
(241785, 14995, 2003, '<td valign="top">looks like an anole to me</td>', 'looks like an anole to me', '2003-03-19 20:00:08.000000', NULL, 1),
(241786, 15004, 5266, '<td valign="top">Beautiful scene.  A bit soft in focus, or is that mist at the mountain tops?</td>', 'Beautiful scene.  A bit soft in focus, or is that mist at the mountain tops?', '2003-03-19 20:00:20.000000', NULL, 1),
(241787, 15039, 6328, '<td valign="top">Now this is certainly different,where were you during the Milk Challenge?  Like the splash and the droplets flying around.  Good focus, good lighting technique, bit if a harsh shadow on the left side.  Like your green and black framing.</td>', 'Now this is certainly different,where were you during the Milk Challenge?  Like the splash and the droplets flying around.  Good focus, good lighting technique, bit if a harsh shadow on the left side.  Like your green and black framing.', '2003-03-19 20:01:00.000000', NULL, 1),
(241788, 14993, 5266, '<td valign="top">I like the detail captured in this photo - the backlighting is great.  The red frames it wonderfully - good choice of subject.</td>', 'I like the detail captured in this photo - the backlighting is great.  The red frames it wonderfully - good choice of subject.', '2003-03-19 20:01:23.000000', NULL, 1),
(241789, 15007, 6328, '<td valign="top">She is really cute, but not as cute as the other lady in green.  Love those beautiful eyes of hers.  Lovely red hair too!  Your background is a good choice of color also. I''m so glad to see that there is no shadow against the background!</td>', 'She is really cute, but not as cute as the other lady in green.  Love those beautiful eyes of hers.  Lovely red hair too!  Your background is a good choice of color also. I''m so glad to see that there is no shadow against the background!', '2003-03-19 20:02:35.000000', NULL, 1),
(241790, 15127, 5266, '<td valign="top">You have to have a strong stomach to eat one of these!!  The green cream cheese is a bit shiny - is it really cream cheese?  There''s a bit too much reflection off the bagel, but the red background is great.</td>', 'You have to have a strong stomach to eat one of these!!  The green cream cheese is a bit shiny - is it really cream cheese?  There''s a bit too much reflection off the bagel, but the red background is great.', '2003-03-19 20:02:51.000000', NULL, 1),
(241791, 15006, 5266, '<td valign="top">Good subject - I like the different colors you have captured in the patina of the statue.</td>', 'Good subject - I like the different colors you have captured in the patina of the statue.', '2003-03-19 20:03:39.000000', NULL, 1),
(241793, 15130, 5266, '<td valign="top">You gotta love green beer!!  I would have liked to see a bit more head on the beer, or more bubbles in the glass (stir it up!!)  I think a white label on the glass would be nice, but you gotta love green beer!!  Slainte Mhath!!</td>', 'You gotta love green beer!!  I would have liked to see a bit more head on the beer, or more bubbles in the glass (stir it up!!)  I think a white label on the glass would be nice, but you gotta love green beer!!  Slainte Mhath!!', '2003-03-19 20:06:02.000000', NULL, 1),
(241794, 15000, 5266, '<td valign="top">Nice textures with the ice crystals.  I like that some of the peas have freezer burn.</td>', 'Nice textures with the ice crystals.  I like that some of the peas have freezer burn.', '2003-03-19 20:06:59.000000', NULL, 1),
(241795, 15000, 6405, '<td valign="top">Good light,good focus,good composition.my second best photo!</td>', 'Good light,good focus,good composition.my second best photo!', '2003-03-19 20:07:15.000000', NULL, 1),
(241796, 15149, 5266, '<td valign="top">Nice shot - I like the angle you have chosen.  Very original idea!!</td>', 'Nice shot - I like the angle you have chosen.  Very original idea!!', '2003-03-19 20:07:28.000000', NULL, 1),
(241797, 15148, 5266, '<td valign="top">The ducks seem to be moving a bit too fast here - the focus is soft.</td>', 'The ducks seem to be moving a bit too fast here - the focus is soft.', '2003-03-19 20:08:07.000000', NULL, 1),
(241798, 14965, 6405, '<td valign="top">centered,nice contrast ,well done,8 from me!</td>', 'centered,nice contrast ,well done,8 from me!', '2003-03-19 20:08:08.000000', NULL, 1),
(241799, 15136, 5266, '<td valign="top">This is a beautiful photo of a beautiful flower, but the green just doesn''t stand out, so I don''t feel it really meets the challenge well.</td>', 'This is a beautiful photo of a beautiful flower, but the green just doesn''t stand out, so I don''t feel it really meets the challenge well.', '2003-03-19 20:08:45.000000', NULL, 1),
(241800, 15036, 6405, '<td valign="top">WOW!!!beutiful skin color,very sharp,you will get the ribbon, excellent!! 10 here!</td>', 'WOW!!!beutiful skin color,very sharp,you will get the ribbon, excellent!! 10 here!', '2003-03-19 20:09:26.000000', NULL, 1),
(241801, 15144, 5266, '<td valign="top">Very little green here.  Just the serial number.</td>', 'Very little green here.  Just the serial number.', '2003-03-19 20:09:46.000000', NULL, 1),
(241802, 15122, 6405, '<td valign="top">Nice stock photo!</td>', 'Nice stock photo!', '2003-03-19 20:10:12.000000', NULL, 1),
(241803, 15043, 5266, '<td valign="top">Cute little subject.  Something seems to be astray in the bottom left corner - what is that distracting little thing?</td>', 'Cute little subject.  Something seems to be astray in the bottom left corner - what is that distracting little thing?', '2003-03-19 20:10:26.000000', NULL, 1),
(241804, 15023, 5266, '<td valign="top">Focus seems a bit off to me - I like the water droplets.</td>', 'Focus seems a bit off to me - I like the water droplets.', '2003-03-19 20:11:00.000000', NULL, 1),
(241805, 15128, 5266, '<td valign="top">The DOF is a bit off here - I''d like to seee the entire bark in focus.  Great detail on the bark that is in focus!!</td>', 'The DOF is a bit off here - I''d like to seee the entire bark in focus.  Great detail on the bark that is in focus!!', '2003-03-19 20:11:45.000000', NULL, 1),
(241870, 14992, 2553, '<td valign="top">Pretty cool, I like the whole feel of this shot.  Good color, pretty good lighting and I like the negative space - I don''t think it would have had as much impact with any other kind of background.</td>', 'Pretty cool, I like the whole feel of this shot.  Good color, pretty good lighting and I like the negative space - I don''t think it would have had as much impact with any other kind of background.', '2003-03-19 22:16:08.000000', NULL, 1),
(241872, 15140, 2553, '<td valign="top">Love the image of the plant with all the lines and angles, and the lighting and color are great.  Don''t like the distracting images behind the plant.</td>', 'Love the image of the plant with all the lines and angles, and the lighting and color are great.  Don''t like the distracting images behind the plant.', '2003-03-19 22:17:15.000000', NULL, 1),
(241875, 15008, 2553, '<td valign="top">Love this image.  The flow of the lines is beautiful, and all the repeating patterns really make it an interesting image.  I really like the backlight, but wonder if you could have had a little more light on the front side of the leaf without losing the clarity of the lines.</td>', 'Love this image.  The flow of the lines is beautiful, and all the repeating patterns really make it an interesting image.  I really like the backlight, but wonder if you could have had a little more light on the front side of the leaf without losing the clarity of the lines.', '2003-03-19 22:19:07.000000', NULL, 1),
(241876, 14965, 2553, '<td valign="top">Great color, and nice composition and lighting.  Love the repeating lines and angles.</td>', 'Great color, and nice composition and lighting.  Love the repeating lines and angles.', '2003-03-19 22:19:59.000000', NULL, 1),
(241878, 15033, 3084, '<td valign="top">I am Canadian and I am GREEN with envy</td>', 'I am Canadian and I am GREEN with envy', '2003-03-19 22:20:52.000000', NULL, 1),
(241881, 14988, 3084, '<td valign="top">Fun form</td>', 'Fun form', '2003-03-19 22:21:39.000000', NULL, 1),
(241883, 15008, 3084, '<td valign="top">Great texture and wonderful image</td>', 'Great texture and wonderful image', '2003-03-19 22:22:21.000000', NULL, 1),
(241900, 15116, 2779, '<td valign="top">it would have been better if where a rolling rock bottle!</td>', 'it would have been better if where a rolling rock bottle!', '2003-03-19 22:51:51.000000', NULL, 1),
(241953, 15116, 7190, '<td valign="top">I think that the image is croped too tight would like tosee more space on top and more of the shadow,</td>', 'I think that the image is croped too tight would like tosee more space on top and more of the shadow,', '2003-03-19 23:55:32.000000', NULL, 1),
(241962, 15008, 6328, '<td valign="top">Focus is good, good idea for the Challenge,<br/>Colours are really nice, lighting is really different the way you have it coming through like this.<br/></td>', 'Focus is good, good idea for the Challenge,Colours are really nice, lighting is really different the way you have it coming through like this.', '2003-03-20 00:21:32.000000', NULL, 1),
(241963, 15104, 6328, '<td valign="top">Now that''s really different and original.  You really use the rule of 3rds too!</td>', 'Now that''s really different and original.  You really use the rule of 3rds too!', '2003-03-20 00:22:44.000000', NULL, 1),
(241964, 14995, 6328, '<td valign="top">Really nice photo of the Iguana.  Nice coloring to it, nice focus too.</td>', 'Really nice photo of the Iguana.  Nice coloring to it, nice focus too.', '2003-03-20 00:23:54.000000', NULL, 1),
(241965, 15125, 6328, '<td valign="top">Nice color to your photograph, good lighting technique.  I like your focus and sharpness.</td>', 'Nice color to your photograph, good lighting technique.  I like your focus and sharpness.', '2003-03-20 00:25:47.000000', NULL, 1),
(241972, 14992, 6019, '<td valign="top">great idea... well done!!</td>', 'great idea... well done!!', '2003-03-20 00:42:57.000000', NULL, 1),
(241973, 15022, 6019, '<td valign="top">lovely idea, well done!!</td>', 'lovely idea, well done!!', '2003-03-20 00:43:17.000000', NULL, 1),
(242007, 15138, 6405, '<td valign="top">Construction equipment ruined the photo,otherwise would be very nice!</td>', 'Construction equipment ruined the photo,otherwise would be very nice!', '2003-03-20 07:30:13.000000', NULL, 1),
(242008, 15039, 6405, '<td valign="top">Would be nice if it was in focus!</td>', 'Would be nice if it was in focus!', '2003-03-20 07:34:30.000000', NULL, 1),
(242046, 14995, 772, '<td valign="top">beautiful shot... the green is quite striking... i love the composition also... great work :) = 10 - setzler</td>', 'beautiful shot... the green is quite striking... i love the composition also... great work :) = 10 - setzler', '2003-03-20 09:29:21.000000', NULL, 1),
